Rules.InvariantScript:
Set(varSettingsGrantApprover, false);
Set(varSettingsGrantAdmin, false);
Set(varSettingsSelectedEmail, "");
Set(varSettingsSelectedName, "");
Set(varSettingsFilter, "");
Reset(Dropdown_SettingsEmployee);
Reset(txt_ActiveUsersFilter);
Reset(chk_ApproverOfAll);
Reset(chk_Admin);
Refresh('Hours Tracking (Active Users)');
Refresh('Hours Tracking (Permissions)');
ClearCollect(colActiveUsers, 'Hours Tracking (Active Users)');
ClearCollect(colPermissions, 'Hours Tracking (Permissions)');

If(
    !IsBlank(Trim(Self.SearchText)),
    ShowColumns(
        Office365Users.SearchUser(
            {
                searchTerm: Trim(Self.SearchText),
                top: 15
            }
        ),
        Id,
        DisplayName,
        Mail,
        UserPrincipalName,
        Department
    )
)

Set(
    varSettingsSelectedEmail,
    Lower(Coalesce(Self.Selected.Mail, Self.Selected.UserPrincipalName))
);
Set(varSettingsSelectedName, Self.Selected.DisplayName);

Refresh('Hours Tracking (Active Users)');
Refresh('Hours Tracking (Permissions)');
ClearCollect(colActiveUsers, 'Hours Tracking (Active Users)');
ClearCollect(colPermissions, 'Hours Tracking (Permissions)');

If(
    varIsSavingSettings,
    Notify("Please wait...", NotificationType.Warning),
    IsBlank(varSettingsSelectedEmail),
    Notify("Select a person first", NotificationType.Warning),
    Set(varIsSavingSettings, true);
    Set(
        varSettingsEntraId,
        Office365Users.UserProfileV2(varSettingsSelectedEmail).id
    );
    With(
        {
            existingAU: LookUp(
                colActiveUsers,
                Lower(Title) = varSettingsSelectedEmail
            )
        },
        If(
            !IsBlank(existingAU),
            If(
                IsBlank(existingAU.Entra_ID),
                Patch(
                    'Hours Tracking (Active Users)',
                    LookUp('Hours Tracking (Active Users)', ID = existingAU.ID),
                    {
                        Name: Coalesce(varSettingsSelectedName, existingAU.Name),
                        Entra_ID: varSettingsEntraId
                    }
                );
                Notify("User updated", NotificationType.Success),
                Notify("Already has access", NotificationType.Information)
            ),
            Patch(
                'Hours Tracking (Active Users)',
                Defaults('Hours Tracking (Active Users)'),
                {
                    Title: varSettingsSelectedEmail,
                    Name: varSettingsSelectedName,
                    Entra_ID: varSettingsEntraId
                }
            );
            Notify("Added to app", NotificationType.Success)
        )
    );
    If(
        varSettingsGrantAdmin || varSettingsGrantApprover,
        With(
            {
                existingPerm: LookUp(
                    colPermissions,
                    Lower(User_Email) = varSettingsSelectedEmail
                ),
                writeAdmin: varSettingsGrantAdmin,
                writeApprover: If(varSettingsGrantAdmin || varSettingsGrantApprover, 1, 0)
            },
            If(
                IsBlank(existingPerm),
                Patch(
                    'Hours Tracking (Permissions)',
                    Defaults('Hours Tracking (Permissions)'),
                    {
                        Title: varSettingsSelectedEmail,
                        User_Email: varSettingsSelectedEmail,
                        Approver: writeApprover,
                        IsAdmin: writeAdmin
                    }
                );
                Notify("Permissions saved", NotificationType.Success),
                Patch(
                    'Hours Tracking (Permissions)',
                    LookUp('Hours Tracking (Permissions)', ID = existingPerm.ID),
                    {
                        Approver: Max(Coalesce(existingPerm.Approver, 0), writeApprover),
                        IsAdmin: writeAdmin || Coalesce(existingPerm.IsAdmin, false)
                    }
                );
                Notify("Permissions updated", NotificationType.Success)
            )
        )
    );
    Set(varIsSavingSettings, false);
    Select(btn_ReloadActiveUsers)
)
